import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"地雷复","description":"周易折中 - 地雷复","frontmatter":{"title":"地雷复","description":"周易折中 - 地雷复"},"headers":[],"relativePath":"zh/classics/zhezhong/030.md","filePath":"zh/classics/zhezhong/030.md"}'),h={name:"zh/classics/zhezhong/030.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="地雷复" tabindex="-1">地雷复 <a class="header-anchor" href="#地雷复" aria-label="Permalink to “地雷复”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>复序卦：物不可以终尽，剥穷上反下，故受之以复。物无剥尽之理，故剥极则复来，阴极则阳生，阳剥极于上，而复生于下，穷上而反下也。复所以次剥也，为卦一阳生于五阴之下，阴极而阳复也。岁十月，阴盛既极，冬至则一阳复生于地中，故为复也。阳，君子之道，阳消极而复反，君子之道消极而复长也，故为反善之义。</p><p>复：亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>复，阳复生于下也。剥尽则为纯坤，十月之卦，而阳气已生于下矣。积之逾月，然后一阳之体始成而来复，故十有一月，其卦为复。以其阳既往而复反，故有亨道。又内震外坤，有阳动于下而以顺上行之象，故其占又为己之出入既得无疾，朋类之来亦得无咎。又自五月姤卦一阴始生，至此七爻而一阳来复，乃天运之自然，故其占又为“反复其道，至于七日，当得来复”。又以刚德方长，故其占又为“利有攸往”也。“反复其道”，往而复来，来而复往之意；“七日”，所占来复之期也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>复亨，既复则亨也。阳气复生于下，渐亨盛而生育万物。君子之道既复，则渐以亨通泽于天下，故复则有亨盛之理也。出入无疾，出入谓生长，复生于内入也，长进于外出也。先云出，语顺耳。阳生非自外来，来于内故谓之入。物之始生，其气至微，故多屯艰。阳之始生，其气至微，故多摧折。春阳之发，为阴寒所折，观草木于朝暮则可见矣。出入无疾，谓微阳生长无害之者也。既无害之，而其类渐进而来，则将亨盛，故无咎也。所谓咎，在气则为差忒，在君子则为抑塞不得尽其理。阳之当复，虽使有疾之固，不能止其复也，但为阻碍耳。而卦之才有无疾之义，乃复道之善也。一阳始生，至微固未能胜群阴而发生万物，必待诸阳之来，然后能成生物之功而无差忒，以朋来而无咎也。三阳子丑寅之气生成万物，众阳之功也。若君子之道既消而复，岂能便胜于小人？必待其朋类渐盛，则能协力以胜之也。“反复其道”，谓消长之道反复迭至。阳之消至七日而来复，姤阳之始消也，七变而成复，故云七日。谓七更也。临云“八月有凶”，谓阳长至于阴长，历八月也。阳进则阴退，君子道长则小人道消，故利有攸往也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>房氏乔曰：出入无疾，害之者喜阳气之复；朋来无罪，咎之者欲众阳渐进之意。</p></li><li><p>邵子曰：复次剥，明治生于乱乎；夬次姤，明乱生于治乎。时哉时哉，未有剥而不复，未有夬而不姤者。</p></li><li><p>郑氏刚中曰：七者阳数，日者阳物，故于阳长言七日；八者阴数，月者阴物，临刚长以阴为戒，故曰八月。</p></li><li><p>朱子语类云：七日只取七义，犹八月有凶只取八义。</p></li><li><p>胡氏炳文曰：“反复其道”统言阴阳往来，其理如此；“七日来复”专言一阳往来，其数如此。</p></li><li><p>林氏希元曰：天下事非一人所能独办，君子有为于天下，必与其类同心共济，故复重朋来，而泰重彚征。</p></li><li><p>张氏振渊曰：“反复其道”，犹云反复计其程道也。此二句正见天运自有定期，君子不可不善承之耳。</p></li></ul><p>象曰：雷在地中，复；先王以至日闭关，商旅不行，后不省方</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>安静以养㣲阳也。月令是月斋戒掩身，以待阴阳之所定。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>雷者，阴阳相薄而成声。当阳之㣲，未能发也。雷在地中，阳始复之时也。阳始生于下而甚㣲，安静而后能长。先王顺天道，当至日阳之始生，安静以养之，故闭关使商旅不得行，人君不省视四方。观复之象而顺天道也，在一人之身亦然，当安静以养其阳也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>刘氏蜕曰 ：雷在地中，殷殷隆隆，阳来而复，复来而天下昭融乎。</p></li><li><p>苏氏舜钦曰 ：复其见天地之心乎？王弼解云：“复者，反本之谓，天地以本为心，寂然至无，是其本也。故动息地中，乃天地之心见矣。”予窃惑焉。夫复也者，以一阳始生而得名也。《彖》曰：“刚反”，又曰“刚长”，安得谓寂然至无耶？安得谓动息耶？《象》曰：“雷在地中复”，雷者阳物也，动物也。今在地中，则是有阳动之象也。辅嗣昧举卦之体，乃以寂然至无为复，斯失之矣。又云：“冬至阴之复，夏至阳之复。”何冬夏阴阳之不辨耶？</p></li><li><p>朱子语类 问：阳始生甚㣲，安静而后能长，故复之象曰“先王以至日闭关”，人善端之萌亦甚㣲，须庄敬持养然后能大，不然复亡之矣。 答：然。 问：纯坤之月可谓至静，然昨日之静所以养成今日之动，一阳之复乃是纯阴养得出来。在人则主静而后善端始复。 答：固有此意，但不是此卦大义。大象所谓“至日闭关”者，正是于己动之后要以安静养之。</p></li><li><p>问：阳始生甚㣲，安静而后能长，故复之象曰“先王以至日闭关”，人善端之萌亦甚㣲，须庄敬持养然后能大，不然复亡之矣。 答：然。</p></li><li><p>问：纯坤之月可谓至静，然昨日之静所以养成今日之动，一阳之复乃是纯阴养得出来。在人则主静而后善端始复。 答：固有此意，但不是此卦大义。大象所谓“至日闭关”者，正是于己动之后要以安静养之。</p></li><li><p>杨氏启新曰 ：闭关静以养阳，施命动以制阴。王者于姤复用意深矣。</p></li></ul><p>彖曰：复亨刚反</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>刚反则亨。</p><p>动而以顺行，是以出入无疾，朋来无咎</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦徳而言</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：“复亨者，以阳复则亨，故以亨连复而释之也。刚反动而以顺行者”，既上释“复亨”之义，又下释“出入无疾，朋来无咎”之理。</p></li><li><p>潘氏夣旗曰：“剥以顺而止，复以顺而行。君子处道消之极，至道长之初，未尝一豪之不以顺也。”</p></li></ul><p>反复其道，七日来复，天行也</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>阴阳消息，天运然也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>侯氏行果曰：五月天行至午，阴升也；十一月天行至子，阳升也。天地运往，阴阳升复，凡历七月，故曰“七日来复”。此天之运行也。《豳诗》曰：“一之日觱发，二之日栗烈。”一之日，周之正月也；二之日，周之二月也。则古人呼月为日，明矣。</li></ul><p>利有攸往，刚长也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>以卦体而言，既生则渐长矣。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰：剥曰“不利有攸往”，小人长也；复曰“利有攸往”，刚长也。《易》之意，凡以为君子谋也。</p></li><li><p>丘氏富国曰：刚反，言剥之一刚穷上反下而为复也；刚长，言复之一阳自下进上为临、为泰，以至为干也。以其既去而来反也，故亨；以其既反而渐长也，故“利有攸往”。刚反，言方复之初；刚长，言已复之后。</p></li></ul><p>复其见天地之心乎</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>积阴之下一阳复生，天地生物之心几于灭息，而至此乃复可见。在人则为静极而动，恶极而善，本心几息而复见之端也。程子论之详矣。而邵子之诗亦曰：“冬至子之半，天心无改移。一阳初动处，万物未生时。𤣥酒味方淡，大音声正希。”此言如不信，更请问包义。至哉言也，学者宜尽心焉。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>复亨，谓刚反而亨也。阳刚消极而来反，既来反则渐长盛而亨通矣。动而以顺行，是以出入无疾，朋来无咎。以卦才言其所以然也。下动而上顺，是动而以顺行也。阳刚反而顺动，是以得出入无疾，朋来而无咎也。朋之来亦顺动也。其道反复往来，迭消迭息，七日而来复者，天地之运行如是也。消长相因，天之理也。阳刚君子之道长，故利有攸往。一阳复于下，乃天地生物之心也。先儒皆以静为见天地之心，盖不知动之端乃天地之心也，非知道者孰能识之。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>程子曰：“复其见天地之心，皆谓至静能见天地之心，非也。复之卦，下面一画便是动也，安得谓之静？自古儒者皆言静见天地之心，惟某言动而见天地之心。”或曰：“莫是于动上求静否？”曰：“固是，然最难。”○又曰：“复其见天地之心，一言以蔽之，天地以生物为心。”</p></li><li><p>张子曰：“复言见天地之心，咸、恒、大壮言天地之情。心发乎微，情发乎显。”</p></li><li><p>朱子语类云：“天地以生生为徳，元亨利贞乃生物之心也。但其静而复，乃未发之体；动而通焉，则已发之用。一阳来复，其始生甚微，固若静矣，然动之机日长，而万物莫不资始焉。此天命流行之初，造化发育之始，天地生生不已之心，于是而可见也。若其静而未发，则此心之体虽无所不在，然却有未发见处。此程子所以以动之端为天地之心，亦举用以该其体尔。” 又云：“伊川与濂溪说复字亦差不同。濂溪就回来处说，伊川却正就动处说。如元亨利贞，濂溪就利贞上说复字，伊川就元字头说复字。以周易卦爻之意推之，则伊川之说为正。然濂溪、伊川之说道理只一般，只是所指地头不同。王弼之说与濂溪同。”</p></li><li><p>又云：“伊川与濂溪说复字亦差不同。濂溪就回来处说，伊川却正就动处说。如元亨利贞，濂溪就利贞上说复字，伊川就元字头说复字。以周易卦爻之意推之，则伊川之说为正。然濂溪、伊川之说道理只一般，只是所指地头不同。王弼之说与濂溪同。”</p></li><li><p>胡氏炳文曰：“天地生物之心，即人之本心也，皆于几息而复萌之时见之。”</p></li><li><p>俞氏琰曰：“天地之心，谓天地生万物之心也。天地生物之心无乎不在，圣人于剥反为复，静极动初，见天地生物之心，未尝一日息。非谓惟复卦见天地之心也。或谓静为天地之心，非也。或又谓动为天地之心，亦非也。”</p></li><li><p>呉氏曰愼曰：“天地以生物为心，所谓仁也。复之一阳初动，仁也，故曰复其见天地之心乎。”</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>天地之心在人则为道心也。道心甚微，故曰复小。而辨于物，于是而惟精以察之，惟一以守之，则道心流行而微者著矣。颜子有不善未尝不知，是其精也；知之未尝复行，是其一也。夫子以初爻之义当之者，此也。惟精惟一者，所以执中而已矣。二五皆中，故二则休复而吉，五则敦复而无悔。初爻之外，惟此两爻最善。三则频复而厉者，所谓人心危而难安也；四之中行而独者，所谓道心微而难著也。然皆能自求其心者也。至于上六，则不独微而且迷，不不独危而且败，迷而以至于败，则所谓天君者不能以自主矣。故夫子咎之曰反君道也。尧舜相传之心学，皆于复卦见之。</p><p>初九：不远复，无祗悔，元吉。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>一阳复生于下，复之主也。祗，抵也，又居事初，失之未远，能复于善，不抵于悔，大善而吉之道也。故其象占如此。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>复者，阳反来复也。阳，君子之道，故复为反善之义。初，刚阳来复，处卦之初，复之最先者也，是不远而复也。失而后有复，不失则何复之有？惟失之不远而复，则不至于悔，大善而吉也。祗，宜音柢，抵也。《玉篇》云：“适也。”义亦同。无祗悔，不至于悔也。《坎》卦曰：“祇既平，无咎。”谓至既平也。颜子无形显之过，夫子谓其庶几，乃无祗悔也。过既未形而改，何悔之有？既未能不勉而中所欲不逾矩，是有过也。然其明而刚，故一有不善，未尝不知，既知未尝不遽改，故不至于悔，乃不远复也。祗，陆德明音支。《玉篇》、《五经文字》、《群经音辨》并见衣部。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏时曰：初九阳始生而未形，动之微也。吉凶悔吝生乎动者也。未形而复，其复不远矣，故不至于悔而元吉。</p></li><li><p>俞氏琰曰：初居震动之始，方动即复，是不远而复，复之最先者也，故不至于悔而元吉。</p></li></ul><p>象曰：不远之复，以脩身也</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>不远而复者，君子所以脩其身之道也。学问之道无他，唯其知不善则速改以从善而已。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰 ：所以不远速复者，以能脩正其身，有过则改故也。</li></ul><p>六二：休复，吉。</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>柔顺中正，近于初九而能下之，复之休美，吉之道也。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>二虽阴爻，处中正而切比于初，志从于阳，能下仁也，复之休美者也。复者，复于礼也，复礼则为仁。初阳复，复于仁也。二比而下之，所以美而吉也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱子语类云：学莫便于近乎仁，既得仁者而亲之，资其善以自益，则力不劳而学美矣，故曰“休复吉”。</li></ul><p>象曰：休复之吉，以下仁也</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>为复之休美而吉者，以其能下仁也。仁者，天下之公善之本也。初复于仁，二能亲而下之，是以吉也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰 ：阳为仁，行己在其上，附而顺之，是降下于仁，所以吉也。</p></li><li><p>张氏栻曰 ：易三百八十四爻，未尝言仁，此独言之，盍有深意。克己复礼为仁，克其私心，复其天理，所以为仁。二去初未远，上无系应，能从初而复，所以为下仁也。至四但言从道而不谓之仁，盖道者举其大凡，不若仁为至切也。</p></li><li><p>俞氏琰曰 ：仁者，心之德，善之本。初九修身而反本复善，可以为仁矣。二之吉，盖以亲近初九而吉也。</p></li></ul><p>六三：频复，厉无咎。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>以阴居阳，不中不正，又处动极，复而不固，屡失屡复之象。屡失故危，复则无咎，故其占又如此。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>三以阴躁处动之极，复之频数而不能固者也。复贵安固，频复频失，不安于复也。复善而屡失，危之道也。圣人开迁善之道，与其复而危，其屡失，故云“厉无咎”，不可以频失而戒其复也。频失则为危，屡复何咎？过在失而不在复也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏忠孝曰：唯君子能久于其道，其馀则日月至焉而已。是以子夏之徒，出见纷华盛丽而悦，入闻夫子之道而乐。与夫回之为人，拳拳服膺而弗失之者，固有间矣。</p></li><li><p>赵氏汝梅曰：三为震动之极，故曰频厉危也，即人心惟危之危。</p></li></ul><p>象曰：频复之厉，义无咎也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>频复频失，虽为危厉，然复善之义则元咎也。</p><p>六四：中行独复。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>四处群阴之中而独与初应为，与众俱行而独能从善之象。当此之时，阳气甚微，未足以有为，故不言吉，然理所当然，吉凶非所论也。董子曰：“仁人者，正其义不谋其利，明其道不计其功。”于剥之六三及此爻见之。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>此爻之义最宜详玩。四行群阴之中而独能复，自处于正，下应于阳刚，其志可谓善矣。不言吉凶者，盖四以柔居群阴之间，初方甚微，不足以相援，无可济之理，故圣人但称其能独复，而不欲言其独从道而必凶也。曰：然则不言无咎何也？曰：以阴居阴，柔弱之甚，虽有从阳之志，终不克济，非无咎也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颍逹曰：中行独复者，处于上卦之下，上下各有二阴，已独应初，居在众阴之中，故云“中行”。独自应初，故云“独复”。</p></li><li><p>缪氏昌期曰：“中”即中以自考之“中”字，“独”即中庸慎独之“独”。四能以中而行，而于独知之中憬然自觉，所谓“复以自知”也。盖复之所以为复，全在初爻，犹人之初念也。五阴皆复此而已，惟四在阴中有所专向，故发此义。</p></li></ul><p>象曰：中行独复，以从道也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>称其独复者，以其从阳刚君子之善道也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰 ：剥六三乃复六四反对，其义相类。在剥取其失上下以应乎阳，在复则取其独复以从道。</li></ul><p>六五：敦复，无悔。</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>以中顺居尊而当复之时，敦复之象，无悔之道也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>六五以中顺之德处君位，能敦笃于复善者也，故无悔。虽本善，戒亦在其中矣。阳复方微之时，以柔居尊，下复无助，未能致亨吉也，能无悔而已。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰：临以上六为敦临，艮以上九为敦艮，皆取积厚之极。复于五即言敦复者，复之上爻迷而不复，故复至五而极也。卦中复者五爻，初最在先，故为不远；五最在后，故为敦。</p></li><li><p>蔡氏渊曰：敦，厚也。坤象。复主初阳，五虽与初无系，而处位得中，能自厚于复者也可以无悔。</p></li><li><p>李氏简曰：初九阳刚，君子之道也。相应相比者，复之易；二与四是也。远而非应者，复之难。六五所以称敦复，敦复者，厚之至也。不与初应，本当有悔，以其能复，是以无悔。</p></li><li><p>胡氏炳文曰：不远复者，善心之萌；敦复者，善行之固。故初九无祗悔，敦复则可无悔矣。不远复入德之事也，敦复其成德之事与。</p></li></ul><p>象曰：敦复无悔，中以自考也</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>考，成也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>以中道自成也。五以阴居尊，处中而体顺，能敦笃其志，以中道自成，则可以无悔也。自成谓成其中顺之德。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏安石曰 ：能以中道自考，则动作不离于中。</p></li><li><p>丘氏富国曰 ：二四待初而复，故曰下仁、曰从道；五不待初而复，故曰自考。</p></li><li><p>李氏简曰 ：中以自考，非自有降衷之性，则亦不能成此德也。</p></li><li><p>梁氏寅曰 ：中以自考，言以其有中德，故能自考其善不善也。</p></li></ul><p>上六：迷复，凶，有灾眚。用行师，终有大败；以其国君凶，至于十年不克征。</p><h3 id="本义-13" tabindex="-1">本义 <a class="header-anchor" href="#本义-13" aria-label="Permalink to “本义”">​</a></h3><p>以阴柔居复终，终迷不复之象，凶之道也。故其占如此，以犹及也。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>以阴柔居复之终，终迷不复者也。述而不复，其凶可知。有灾眚，灾，天灾自外来；眚，已过由自作。既迷不复，善在己则动皆过失，灾祸亦自外而至，盖所招也。迷道不复，无施而可用。以行师，则终有大败；以之为国，则君之凶也。十年者，数之终。至于十年不克征，谓终不能行，既迷于道，何时而可行也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>徐氏几曰：上六，位高而无下仁之美，刚远而无迁善之机，厚极而有难开之蔽，柔终而无改过之勇，是昏迷而不知复者也。</p></li><li><p>杨氏启新曰：心为天君，以其国君言，丧失其本心也。</p></li><li><p>何氏楷曰：坤本先迷，今居其极，则迷之甚矣。言迷复即昏迷而不知所复之谓。行师以下，皆假象以喻，一心不能驭众动，徇物必至丧天君也。</p></li></ul><p>象曰：迷复之凶，反君道也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>复则合道，既迷于复，与道相反也。其凶可知，以其国君凶，谓其反君道也。人君居上而治众，当从天下之善，乃迷于复，反君之道也。非止人君，凡人迷于复者，皆反道而凶也。</p><h3 id="集说-16" tabindex="-1">集说 <a class="header-anchor" href="#集说-16" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏启新曰 ：心为天君，惟君能役群动，而反以群动役，与心之道相背驰者也。</li></ul><p>总论</p><ul><li>胡氏炳文曰：迷复与不远复相反，初不远而复，迷则远而不复；敦复与频复相反，敦无转易，频则屡易；独复与休复相似，休则比初，独则应初也；十年不克征，亦七日来复之反。</li></ul>',118)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
